import os
import re
from pathlib import Path

# Configuration
BASE_DIR = Path(__file__).parent
FLUTTER_ENUM_PATH = BASE_DIR / "../../primecare_adapters/lib/src/registry/05_G_primecare_form_enum.dart"
REGISTRY_DIR = BASE_DIR / "../src/registries/FormRegistry"
SKELETON_FILE = REGISTRY_DIR / "skeleton-forms.ts"

# Interfaces
HEADER = """import { FormEntry } from '../01_I_form_registry';

/**
 * Skeleton Form Definitions
 * Automatically generated by xx_registry_fixer.py.
 * Provides transient placeholders for IDs defined in the Flutter Master Enum 
 * that have not yet been implemented as high-fidelity domain forms.
 */
export const SKELETON_FORMS: FormEntry[] = [
"""

FOOTER = "\n];\n"

def to_label(id_str):
    """Converts camelCase to Space Case with (Skeleton) suffix."""
    label = re.sub(r'([A-Z])', r' \1', id_str)
    return label[0].upper() + label[1:] + " (Skeleton)"

def parse_flutter_enum():
    """Extracts all form IDs from the Dart enum definition."""
    print(f"Scanning Flutter Enum: {FLUTTER_ENUM_PATH}")
    if not FLUTTER_ENUM_PATH.exists():
        print(f"Error: Flutter Enum not found at {FLUTTER_ENUM_PATH}")
        return []
    
    content = FLUTTER_ENUM_PATH.read_text(encoding="utf-8")
    enum_match = re.search(r"enum PrimeCareForm \{([\s\S]*?)\}", content)
    if not enum_match:
        print("Error: Could not find 'enum PrimeCareForm' in Dart file.")
        return []
    
    body = enum_match.group(1)
    # Filter comments and empty lines, extract id before start of metadata
    ids = []
    for line in body.split(","):
        line = line.strip()
        if not line or line.startswith("//") or line == ";":
            continue
        # ID is the part before the first parenthesis or space
        clean_id = re.split(r'\(|\s', line)[0]
        if clean_id:
            ids.append(clean_id)
    
    print(f"Found {len(ids)} unique IDs in Flutter.")
    return ids

def get_implemented_ids():
    """Scans all TS files EXCEPT the skeleton file to find IDs that are already defined."""
    implemented = set()
    print(f"Scanning domain registries in: {REGISTRY_DIR}")
    
    for ts_file in REGISTRY_DIR.glob("*.ts"):
        if ts_file.name == SKELETON_FILE.name:
            continue
            
        content = ts_file.read_text(encoding="utf-8")
        # Match 'id: "something"' or "id: 'something'"
        matches = re.findall(r"id:\s*['\"]([^'\"]+)['\"]", content)
        for m in matches:
            implemented.add(m)
            
    print(f"Found {len(implemented)} implemented high-fidelity forms.")
    return implemented

def fix_registries():
    """Synchronizes registries and updates current skeletons."""
    dart_ids = parse_flutter_enum()
    implemented_ids = get_implemented_ids()
    
    skeletons = [id for id in dart_ids if id not in implemented_ids]
    print(f"Generating {len(skeletons)} skeletons to maintain 100% parity...")
    
    body_lines = []
    for sid in skeletons:
        label = sid.replace('(', ' ').replace(')', '').strip() # Clean nested parens if any
        label = to_label(label)
        entry = f"    {{ id: '{sid}', label: '{label}', category: 'skeleton', fields: [] }}"
        body_lines.append(entry)
        
    skeleton_content = HEADER + ",\n".join(body_lines) + FOOTER
    
    SKELETON_FILE.write_text(skeleton_content, encoding="utf-8")
    print(f"Successfully updated {SKELETON_FILE.name}")
    print(f"System State: {len(implemented_ids)} High-Fidelity | {len(skeletons)} Skeletons | Total: {len(dart_ids)}")

if __name__ == "__main__":
    fix_registries()
